INSERT INTO `tfaqs` VALUES ('FAQ-0001',5,2,NULL,'Apa saja persyaratan dan alur pendaftaran usulan judul Tugas Akhir (TA) di Fakultas Teknik?','2026-10-25 02:00:00','2026-10-25 02:00:00'),('FAQ-0002',5,2,NULL,'Berapa batas minimal SKS yang harus diselesaikan sebelum mengambil Tugas Akhir atau Skripsi Teknik?','2026-10-24 07:15:00','2026-10-24 07:15:00'),('FAQ-0003',6,4,NULL,'Bagaimana prosedur pendaftaran Seminar Proposal (Sempro) Tugas Akhir Fakultas Teknik?','2026-10-23 04:30:00','2026-10-23 04:30:00'),('FAQ-0004',7,7,NULL,'Apa saja berkas kelengkapan untuk mendaftar Sidang Akhir atau Pendadaran Skripsi Fakultas Teknik?','2026-10-22 09:20:00','2026-10-22 09:20:00'),('FAQ-0005',5,2,NULL,'Bagaimana ketentuan dan alur pergantian dosen pembimbing Tugas Akhir di Fakultas Teknik?','2026-10-22 03:45:00','2026-10-22 03:45:00'),('FAQ-0006',6,4,NULL,'Di mana mahasiswa dapat mengunduh format penulisan dan template LaTeX atau Word laporan TA Fakultas Teknik?','2026-10-21 08:10:00','2026-10-21 08:10:00'),('FAQ-0007',7,7,NULL,'Berapa batas maksimal toleransi kesamaan (similarity score) Turnitin untuk naskah skripsi Fakultas Teknik?','2026-10-21 06:00:00','2026-10-21 06:00:00'),('FAQ-0008',5,2,NULL,'Bagaimana prosedur perpanjangan masa Tugas Akhir jika tidak selesai dalam 1 semester di Fakultas Teknik?','2026-10-20 07:25:00','2026-10-20 07:25:00'),('FAQ-0009',6,4,NULL,'Apakah mahasiswa Fakultas Teknik wajib mempublikasikan artikel ilmiah di jurnal atau prosiding untuk syarat kelulusan?','2026-10-20 02:30:00','2026-10-20 02:30:00'),('FAQ-0010',7,7,NULL,'Bagaimana aturan pelaksanaan Capstone Design Project berkelompok lintas disiplin di Fakultas Teknik?','2026-10-19 08:00:00','2026-10-19 08:00:00'),('FAQ-0011',5,2,NULL,'Bagaimana prosedur dan jadwal pendaftaran praktikum laboratorium semester gasal/genap FT?','2026-10-19 04:20:00','2026-10-19 04:20:00'),('FAQ-0012',6,4,NULL,'Bagaimana prosedur peminjaman alat ukur (osiloskop, multimeter, modul mikrokontroler) di laboratorium teknik?','2026-10-18 07:40:00','2026-10-18 07:40:00'),('FAQ-0013',7,7,NULL,'Apa saja syarat dan tata tertib Keselamatan dan Kesehatan Kerja (K3) serta APD di laboratorium teknik?','2026-10-18 03:10:00','2026-10-18 03:10:00'),('FAQ-0014',5,2,NULL,'Bagaimana ketentuan inhal praktikum jika mahasiswa berhalangan hadir karena sakit atau izin resmi?','2026-10-17 09:50:00','2026-10-17 09:50:00'),('FAQ-0015',6,4,NULL,'Bagaimana alur pengajuan izin lembur riset dan pemakaian laboratorium di luar jam operasional kampus FT?','2026-10-17 06:15:00','2026-10-17 06:15:00'),('FAQ-0016',7,7,NULL,'Bagaimana prosedur penggantian komponen atau peralatan laboratorium teknik yang mengalami kerusakan saat praktikum?','2026-10-16 08:40:00','2026-10-16 08:40:00'),('FAQ-0017',5,2,NULL,'Kapan pendaftaran Asisten Laboratorium (Aslab) Fakultas Teknik dibuka dan apa persyaratannya?','2026-10-16 02:20:00','2026-10-16 02:20:00'),('FAQ-0018',6,4,NULL,'Bagaimana cara mengakses komputer workstation simulasi CAD/CAM/CAE dan software engineering berlisensi FT?','2026-10-15 07:00:00','2026-10-15 07:00:00'),('FAQ-0019',7,7,NULL,'Apakah Fakultas Teknik memfasilitasi program sertifikasi internasional keahlian software teknik?','2026-10-15 03:30:00','2026-10-15 03:30:00'),('FAQ-0020',5,2,NULL,'Bagaimana tata cara pembuangan limbah bahan kimia dan pelumas bekas laboratorium FT sesuai standar lingkungan?','2026-10-14 09:10:00','2026-10-14 09:10:00'),('FAQ-0021',6,4,NULL,'Apa saja syarat kelayakan mengambil mata kuliah Kerja Praktik (KP) bagi mahasiswa Fakultas Teknik?','2026-10-14 04:45:00','2026-10-14 04:45:00'),('FAQ-0022',7,7,NULL,'Bagaimana prosedur pembuatan surat pengantar survei industri dan permohonan magang ke perusahaan?','2026-10-13 08:20:00','2026-10-13 08:20:00'),('FAQ-0023',5,2,NULL,'Berapa lama durasi minimal pelaksanaan Kerja Praktik (KP) di industri yang diakui oleh Fakultas Teknik?','2026-10-13 02:30:00','2026-10-13 02:30:00'),('FAQ-0024',6,4,NULL,'Bagaimana mekanisme penyusunan logbook harian dan seminar laporan Kerja Praktik di Fakultas Teknik?','2026-10-12 07:10:00','2026-10-12 07:10:00'),('FAQ-0025',7,7,NULL,'Bagaimana alur konversi mata kuliah program Magang MBKM mandiri/MSIB ke dalam kurikulum program studi teknik?','2026-10-12 03:00:00','2026-10-12 03:00:00'),('FAQ-0026',5,2,NULL,'Apa yang harus dilakukan jika permohonan magang atau Kerja Praktik ditolak oleh perusahaan tujuan?','2026-10-11 08:30:00','2026-10-11 08:30:00'),('FAQ-0027',6,4,NULL,'Bagaimana alur konsultasi perwalian dan pengesahan Kartu Rencana Studi (KRS) dengan Dosen Wali FT?','2026-10-11 02:15:00','2026-10-11 02:15:00'),('FAQ-0028',7,7,NULL,'Bagaimana aturan sistem prasyarat mata kuliah (prerequisite chain) pada kurikulum Fakultas Teknik?','2026-10-10 07:00:00','2026-10-10 07:00:00'),('FAQ-0029',5,2,NULL,'Apakah mahasiswa Fakultas Teknik diperbolehkan mengambil mata kuliah di program studi teknik yang lain?','2026-10-10 03:25:00','2026-10-10 03:25:00'),('FAQ-0030',6,4,NULL,'Berapa batas maksimal masa studi (Drop Out / DO) untuk jenjang Program Sarjana (S1) Fakultas Teknik?','2026-10-09 06:50:00','2026-10-09 06:50:00'),('FAQ-0031',7,7,NULL,'Bagaimana ketentuan pelaksanaan Semester Antara (Semester Pendek) untuk perbaikan nilai mata kuliah teknik?','2026-10-09 02:00:00','2026-10-09 02:00:00'),('FAQ-0032',5,2,NULL,'Bagaimana prosedur permohonan Surat Keterangan Masih Kuliah untuk tunjangan orang tua di FT?','2026-10-08 07:15:00','2026-10-08 07:15:00'),('FAQ-0033',6,4,NULL,'Bagaimana syarat dan prosedur pengajuan cuti akademik sementara bagi mahasiswa Fakultas Teknik?','2026-10-08 03:40:00','2026-10-08 03:40:00'),('FAQ-0034',7,7,NULL,'Bagaimana alur dan syarat pengajuan pindah program studi internal di lingkungan Fakultas Teknik?','2026-10-07 08:00:00','2026-10-07 08:00:00'),('FAQ-0035',5,2,NULL,'Apa saja kelengkapan berkas yang harus diunggah untuk pendaftaran Yudisium Fakultas Teknik?','2026-10-07 04:20:00','2026-10-07 04:20:00'),('FAQ-0036',6,4,NULL,'Berapa batas skor minimal sertifikat tes kemampuan bahasa Inggris (TOEFL/EPT) untuk syarat kelulusan FT?','2026-10-06 07:45:00','2026-10-06 07:45:00'),('FAQ-0037',7,7,NULL,'Bagaimana prosedur pengurusan bebas tanggungan laboratorium dan perpustakaan teknik sebelum yudisium?','2026-10-06 02:30:00','2026-10-06 02:30:00'),('FAQ-0038',5,2,NULL,'Bagaimana cara mendapatkan Surat Keterangan Lulus (SKL) sementara sebelum ijazah asli diterbitkan?','2026-10-05 08:10:00','2026-10-05 08:10:00'),('FAQ-0039',6,4,NULL,'Bagaimana prosedur pengajuan bantuan pendanaan proposal lomba inovasi teknologi dan robotika (PKM/KRI) FT?','2026-10-05 03:00:00','2026-10-05 03:00:00'),('FAQ-0040',7,7,NULL,'Bagaimana prosedur pengajuan dispensasi perkuliahan bagi mahasiswa delegasi kompetisi teknik nasional?','2026-10-04 06:30:00','2026-10-04 06:30:00'),('FAQ-0041',5,2,NULL,'Persyaratan yudisium program sarjana Fakultas Teknik','2026-10-21 03:18:00','2026-10-21 03:18:00'),('FAQ-0042',6,4,NULL,'Apa saja persyaratan pendaftaran tugas akhir Fakultas Teknik?','2026-10-17 04:20:00','2026-10-17 04:20:00'),('FAQ-0043',7,7,NULL,'Bagaimana cara mendapatkan akses server GPU untuk riset kecerdasan buatan di FT?','2026-10-13 06:45:00','2026-10-13 06:45:00'),('FAQ-0044',6,4,NULL,'Ketentuan program magang industri bersertifikat kurikulum lama Fakultas Teknik','2026-10-10 01:20:00','2026-10-10 01:20:00'),('FAQ-0045',6,4,NULL,'Bagaimana cara melakukan pengisian KRS semester baru?','2026-10-21 02:45:00','2026-10-21 02:45:00'),('FAQ-0046',5,2,NULL,'Bagaimana prosedur pengajuan surat aktif kuliah?','2026-10-20 08:30:00','2026-10-20 08:30:00'),('FAQ-0047',7,7,NULL,'Bagaimana cara mengajukan legalisasi transkrip nilai?','2026-10-20 06:12:00','2026-10-20 06:12:00'),('FAQ-0048',7,7,NULL,'Bagaimana prosedur pengajuan pindah program studi?','2026-10-17 01:35:00','2026-10-17 01:35:00'),('FAQ-0049',5,2,NULL,'Mekanisme rekognisi SKS magang MBKM mandiri di Fakultas Bisnis dan Ekonomika','2026-10-16 07:20:00','2026-10-16 07:20:00'),('FAQ-0050',6,4,NULL,'Syarat keikutsertaan peradilan semu (Moot Court) Fakultas Hukum','2026-10-16 03:05:00','2026-10-16 03:05:00'),('FAQ-0051',5,2,NULL,'Bagaimana prosedur permohonan keringanan dan cicilan UKT?','2026-10-15 04:10:00','2026-10-15 04:10:00'),('FAQ-0052',6,4,NULL,'Alur pendaftaran seminar proposal skripsi Fakultas Bisnis dan Ekonomika','2026-10-14 02:30:00','2026-10-14 02:30:00'),('FAQ-0053',5,2,NULL,'Tata tertib dan persyaratan rotasi klinis kepaniteraan (koas) Fakultas Kedokteran','2026-10-12 09:00:00','2026-10-12 09:00:00'),('FAQ-0054',7,7,NULL,'Prosedur keselamatan kerja (K3) dan pembuangan limbah B3 laboratorium FST','2026-10-11 03:15:00','2026-10-11 03:15:00');
/*!40000 ALTER TABLE `tfaqs` ENABLE KEYS */;
UNLOCK TABLES;
DROP TABLE IF EXISTS `tfaqsversion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tfaqsversion` (
  `id` varchar(15) NOT NULL,
  `tDaftarPustakas_id` int(11) DEFAULT NULL,
  `tFaqs_id` varchar(20) NOT NULL,
  `version_number` smallint(5) unsigned NOT NULL DEFAULT 1,
  `id_validator` int(11) DEFAULT NULL,
  `jawaban` text NOT NULL,
  `jawaban_sebelumnya` text DEFAULT NULL,
  `status` enum('Draf','Menunggu Validasi Unit','Menunggu Validasi Admik','Diterima','Ditolak','Terbit') NOT NULL DEFAULT 'Draf',
  `rejected_by_stage` enum('unit','admik') DEFAULT NULL,
  `is_latest` tinyint(1) NOT NULL DEFAULT 0,
  `catatan` text DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `fk_tFaqsVersion_tDaftarPustaka1` (`tDaftarPustakas_id`),
  KEY `fk_tFaqsVersion_tUsers1` (`id_validator`),
  KEY `idx_tfaqsversion_faq_ver` (`tFaqs_id`,`version_number`),
  KEY `idx_tfaqsversion_latest_status` (`is_latest`,`status`,`tFaqs_id`),
  KEY `idx_tfaqsversion_faq_latest_status` (`tFaqs_id`,`is_latest`,`status`),
  KEY `idx_tfaqsversion_status_updated` (`status`,`updated_at`),
  KEY `idx_tfaqsversion_updated_at` (`updated_at`),
  CONSTRAINT `fk_tFaqsVersion_tDaftarPustaka1` FOREIGN KEY (`tDaftarPustakas_id`) REFERENCES `tdaftarpustaka` (`id`),
  CONSTRAINT `fk_tFaqsVersion_tFaqs1` FOREIGN KEY (`tFaqs_id`) REFERENCES `tfaqs` (`id`),
  CONSTRAINT `fk_tFaqsVersion_tUsers1` FOREIGN KEY (`id_validator`) REFERENCES `tusers` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

LOCK TABLES `tfaqsversion` WRITE;
/*!40000 ALTER TABLE `tfaqsversion` DISABLE KEYS */;
INSERT INTO `tfaqsversion` VALUES ('FAQ-0001-V1',NULL,'FAQ-0001',1,3,'Mahasiswa Fakultas Teknik yang telah menyelesaikan minimal 120 SKS dengan IPK >= 2.00 tanpa nilai E dapat mengajukan usulan judul TA melalui SIM Tugas Akhir FT. Langkahnya: (1) Mengunduh formulir pengajuan judul, (2) Melakukan konsultasi dan persetujuan calon Dosen Pembimbing, (3) Mengunggah formulir bersama transkrip nilai terakhir, (4) Menunggu verifikasi dari Koordinator TA Departemen. (Edisi awal panduan akademik sebelum penyesuaian alur daring).',NULL,'Terbit',NULL,1,NULL,'2026-08-30 02:00:00','2026-08-30 02:00:00'),('FAQ-0001-V2',5,'FAQ-0001',1,3,'Mahasiswa Fakultas Teknik yang telah menyelesaikan minimal 120 SKS dengan IPK >= 2.00 tanpa nilai E dapat mengajukan usulan judul TA melalui SIM Tugas Akhir FT. Langkahnya: (1) Mengunduh formulir pengajuan judul, (2) Melakukan konsultasi dan persetujuan calon Dosen Pembimbing, (3) Mengunggah formulir bersama transkrip nilai terakhir, (4) Menunggu verifikasi dari Koordinator TA Departemen. (Pembaruan prosedur pengajuan melalui portal layanan mahasiswa).',NULL,'Terbit',NULL,1,NULL,'2026-09-13 02:00:00','2026-09-13 02:00:00'),('FAQ-0001-V3',5,'FAQ-0001',1,3,'Mahasiswa Fakultas Teknik yang telah menyelesaikan minimal 120 SKS dengan IPK >= 2.00 tanpa nilai E dapat mengajukan usulan judul TA melalui SIM Tugas Akhir FT. Langkahnya: (1) Mengunduh formulir pengajuan judul, (2) Melakukan konsultasi dan persetujuan calon Dosen Pembimbing, (3) Mengunggah formulir bersama transkrip nilai terakhir, (4) Menunggu verifikasi dari Koordinator TA Departemen. (Penyesuaian syarat administrasi dan jadwal verifikasi fakultas).',NULL,'Terbit',NULL,1,NULL,'2026-09-27 02:00:00','2026-09-27 02:00:00'),('FAQ-0001-V4',5,'FAQ-0001',1,3,'Mahasiswa Fakultas Teknik yang telah menyelesaikan minimal 120 SKS dengan IPK >= 2.00 tanpa nilai E dapat mengajukan usulan judul TA melalui SIM Tugas Akhir FT. Langkahnya: (1) Mengunduh formulir pengajuan judul, (2) Melakukan konsultasi dan persetujuan calon Dosen Pembimbing, (3) Mengunggah formulir bersama transkrip nilai terakhir, (4) Menunggu verifikasi dari Koordinator TA Departemen. (Penyempurnaan rincian dokumen pendukung dan ketentuan terbaru).',NULL,'Terbit',NULL,1,NULL,'2026-10-11 02:00:00','2026-10-11 02:00:00'),('FAQ-0001-V5',5,'FAQ-0001',1,3,'Mahasiswa Fakultas Teknik yang telah menyelesaikan minimal 120 SKS dengan IPK >= 2.00 tanpa nilai E dapat mengajukan usulan judul TA melalui SIM Tugas Akhir FT. Langkahnya: (1) Mengunduh formulir pengajuan judul, (2) Melakukan konsultasi dan persetujuan calon Dosen Pembimbing, (3) Mengunggah formulir bersama transkrip nilai terakhir, (4) Menunggu verifikasi dari Koordinator TA Departemen.',NULL,'Terbit',NULL,1,'Pedoman TA Fakultas Teknik 2026.','2026-10-25 02:00:00','2026-10-25 02:00:00'),('FAQ-0002-V1',5,'FAQ-0002',1,3,'Batas minimal beban SKS untuk memprogram mata kuliah Tugas Akhir pada Kartu Rencana Studi (KRS) Fakultas Teknik adalah 120 SKS, telah lulus mata kuliah Metodologi Penelitian dan Kerja Praktik (KP), serta tidak memiliki tunggakan biaya perkuliahan. (Edisi awal panduan akademik sebelum penyesuaian alur daring).',NULL,'Terbit',NULL,1,NULL,'2026-09-12 07:15:00','2026-09-12 07:15:00'),('FAQ-0002-V2',5,'FAQ-0002',1,3,'Batas minimal beban SKS untuk memprogram mata kuliah Tugas Akhir pada Kartu Rencana Studi (KRS) Fakultas Teknik adalah 120 SKS, telah lulus mata kuliah Metodologi Penelitian dan Kerja Praktik (KP), serta tidak memiliki tunggakan biaya perkuliahan. (Pembaruan prosedur pengajuan melalui portal layanan mahasiswa).',NULL,'Terbit',NULL,1,NULL,'2026-09-26 07:15:00','2026-09-26 07:15:00'),('FAQ-0002-V3',5,'FAQ-0002',1,3,'Batas minimal beban SKS untuk memprogram mata kuliah Tugas Akhir pada Kartu Rencana Studi (KRS) Fakultas Teknik adalah 120 SKS, telah lulus mata kuliah Metodologi Penelitian dan Kerja Praktik (KP), serta tidak memiliki tunggakan biaya perkuliahan. (Penyesuaian syarat administrasi dan jadwal verifikasi fakultas).',NULL,'Terbit',NULL,1,NULL,'2026-10-10 07:15:00','2026-10-10 07:15:00'),('FAQ-0002-V4',5,'FAQ-0002',1,3,'Batas minimal beban SKS untuk memprogram mata kuliah Tugas Akhir pada Kartu Rencana Studi (KRS) Fakultas Teknik adalah 120 SKS, telah lulus mata kuliah Metodologi Penelitian dan Kerja Praktik (KP), serta tidak memiliki tunggakan biaya perkuliahan.',NULL,'Terbit',NULL,1,NULL,'2026-10-24 07:15:00','2026-10-24 07:15:00'),('FAQ-0003-V1',5,'FAQ-0003',1,3,'Pendaftaran seminar proposal TA dilakukan setelah draf Bab 1-3 disetujui oleh Dosen Pembimbing Utama dan Pendamping. Berkas yang harus diunggah meliputi lembar persetujuan sempro bertanda tangan, bukti logbook bimbingan minimal 6 kali, naskah proposal format PDF, dan sertifikat kehadiran sempro mahasiswa lain minimal 5 kali.',NULL,'Terbit',NULL,1,'Sudah diverifikasi validator.','2026-10-23 04:30:00','2026-10-23 04:30:00'),('FAQ-0004-V1',NULL,'FAQ-0004',1,3,'Berkas pendaftaran sidang sarjana teknik meliputi: (1) Naskah lengkap laporan TA yang disetujui seluruh pembimbing, (2) Hasil cek similarity Turnitin maksimal 20%, (3) Transkrip nilai bebas nilai D berlebih dan tanpa nilai E, (4) Sertifikat TOEFL skor min. 475, (5) Bukti bebas laboratorium teknik, dan (6) Logbook bimbingan minimal 12 kali pertemuan. (Edisi awal panduan akademik sebelum penyesuaian alur daring).',NULL,'Terbit',NULL,1,NULL,'2026-09-10 09:20:00','2026-09-10 09:20:00'),('FAQ-0004-V2',5,'FAQ-0004',1,3,'Berkas pendaftaran sidang sarjana teknik meliputi: (1) Naskah lengkap laporan TA yang disetujui seluruh pembimbing, (2) Hasil cek similarity Turnitin maksimal 20%, (3) Transkrip nilai bebas nilai D berlebih dan tanpa nilai E, (4) Sertifikat TOEFL skor min. 475, (5) Bukti bebas laboratorium teknik, dan (6) Logbook bimbingan minimal 12 kali pertemuan. (Pembaruan prosedur pengajuan melalui portal layanan mahasiswa).',NULL,'Terbit',NULL,1,NULL,'2026-09-24 09:20:00','2026-09-24 09:20:00'),('FAQ-0004-V3',5,'FAQ-0004',1,3,'Berkas pendaftaran sidang sarjana teknik meliputi: (1) Naskah lengkap laporan TA yang disetujui seluruh pembimbing, (2) Hasil cek similarity Turnitin maksimal 20%, (3) Transkrip nilai bebas nilai D berlebih dan tanpa nilai E, (4) Sertifikat TOEFL skor min. 475, (5) Bukti bebas laboratorium teknik, dan (6) Logbook bimbingan minimal 12 kali pertemuan. (Penyesuaian syarat administrasi dan jadwal verifikasi fakultas).',NULL,'Terbit',NULL,1,NULL,'2026-10-08 09:20:00','2026-10-08 09:20:00'),('FAQ-0004-V4',5,'FAQ-0004',1,3,'Berkas pendaftaran sidang sarjana teknik meliputi: (1) Naskah lengkap laporan TA yang disetujui seluruh pembimbing, (2) Hasil cek similarity Turnitin maksimal 20%, (3) Transkrip nilai bebas nilai D berlebih dan tanpa nilai E, (4) Sertifikat TOEFL skor min. 475, (5) Bukti bebas laboratorium teknik, dan (6) Logbook bimbingan minimal 12 kali pertemuan.',NULL,'Terbit',NULL,1,NULL,'2026-10-22 09:20:00','2026-10-22 09:20:00'),('FAQ-0005-V1',1,'FAQ-0005',1,3,'Pergantian dosen pembimbing dapat diajukan jika dosen bersangkutan tugas belajar, sakit lebih dari 3 bulan, atau terjadi perubahan arah topik penelitian. Mahasiswa mengajukan formulir permohonan pergantian pembimbing yang diketahui dosen pembimbing lama dan baru kepada Ketua Program Studi untuk diterbitkan SK revisi Dekan. (Edisi awal panduan akademik sebelum penyesuaian alur daring).',NULL,'Terbit',NULL,1,NULL,'2026-08-27 03:45:00','2026-08-27 03:45:00'),('FAQ-0005-V2',1,'FAQ-0005',1,3,'Pergantian dosen pembimbing dapat diajukan jika dosen bersangkutan tugas belajar, sakit lebih dari 3 bulan, atau terjadi perubahan arah topik penelitian. Mahasiswa mengajukan formulir permohonan pergantian pembimbing yang diketahui dosen pembimbing lama dan baru kepada Ketua Program Studi untuk diterbitkan SK revisi Dekan. (Pembaruan prosedur pengajuan melalui portal layanan mahasiswa).',NULL,'Terbit',NULL,1,NULL,'2026-09-10 03:45:00','2026-09-10 03:45:00'),('FAQ-0005-V3',1,'FAQ-0005',1,3,'Pergantian dosen pembimbing dapat diajukan jika dosen bersangkutan tugas belaj